import React from "react";
import {
  FaTrophy,
  FaProjectDiagram,
  FaCalendarAlt,
  FaPalette,
  FaBolt,
  FaUserGraduate,
  FaLeaf,
  FaBrain
} from "react-icons/fa";

const Projects = () => {
  return (
    <section className="projects-page">

      {/* HEADER */}
      <div className="section-header">
        <h2>Digital Build Space</h2>
        <p>Showcasing ideas transformed into structured, scalable and interactive systems.</p>
      </div>

      {/* PROJECTS */}
      <div className="section projects-section">

        <div className="projects-grid">

          {/* 01 */}
          <div className="project-card">
            <div className="badge">01</div>
            <div className="project-icon"><FaBolt /></div>
            <h3>EnergyPulse</h3>
            <p>
              Developed the frontend of an AI-driven smart home solution, creating a responsive dashboard that displays real-time biometric and energy data.
              The interface enables users to monitor and control devices easily.
            </p>
            <div className="tech-tags">
              <span>React.js</span>
            </div>
          </div>

          {/* 02 */}
          <div className="project-card">
            <div className="badge">02</div>
            <div className="project-icon"><FaUserGraduate /></div>
            <h3>Student Portal Management</h3>
            <p>
              Developed a full-stack Student Portal Management System using Java and Spring Boot with structured backend and clean UI.
            </p>
            <div className="tech-tags">
              <span>Spring Boot</span>
              <span>HTML</span>
              <span>CSS</span>
              <span>JavaScript</span>
              <span>MySQL</span>
            </div>
          </div>

          {/* 03 */}
          <div className="project-card">
            <div className="badge">03</div>
            <div className="project-icon"><FaLeaf /></div>
            <h3>Farm2Fork</h3>
            <p>
              Built a responsive frontend interface enabling seamless interaction between farmers and consumers.
            </p>
            <div className="tech-tags">
              <span>HTML</span>
              <span>CSS</span>
              <span>JavaScript</span>
            </div>
          </div>

          {/* 04 Cogni Flow */}
          <div className="project-card">
            <div className="badge">04</div>
            <div className="project-icon cogni">
              <FaBrain />
            </div>
            <h3>Cogni Flow</h3>
            <p>
              Designed an interactive learning-based frontend system focused on structured cognitive flow and smooth UI transitions.
            </p>
            <div className="tech-tags">
              <span>HTML</span>
              <span>CSS</span>
              <span>JavaScript</span>
            </div>
          </div>

        </div>
      </div>

      {/* ACHIEVEMENTS */}
      <div className="section achievements-section">
        <h2>Achievements</h2>

        <div className="achievements-grid">

          <div className="achievement-card">
            <FaTrophy className="achievement-icon" />
            <div>
              <h3>Hackathon</h3>
              <p>Semifinalist in Smart India Hackathon (SIH) 2025.</p>
            </div>
          </div>

          <div className="achievement-card">
            <FaProjectDiagram className="achievement-icon" />
            <div>
              <h3>Project Competitions</h3>
              <p>Won Best Project Award for Li-Fi technology project.</p>
            </div>
          </div>

          <div className="achievement-card">
            <FaCalendarAlt className="achievement-icon" />
            <div>
              <h3>Tech Events</h3>
              <p>Organized Code Crunch coding competition event.</p>
            </div>
          </div>

          <div className="achievement-card">
            <FaPalette className="achievement-icon" />
            <div>
              <h3>Non Tech Events</h3>
              <p>Conducted Fun Spin Round and managed participants.</p>
            </div>
          </div>

        </div>
      </div>

      {/* STYLE */}
      <style>{`

        .projects-page {
          min-height: 100vh;
          padding: 40px 10%;
          font-family: "Poppins", sans-serif;
          background: radial-gradient(circle at top, #0b1220, #050816);
          color: white;
        }

        /* HEADER */
        .section-header {
          margin-bottom: 30px;
        }

        .section-header h2 {
          font-size: 34px;
          color: #38BDF8;
          margin-bottom: 6px;
        }

        .section-header p {
          color: #94a3b8;
          font-size: 14px;
          max-width: 600px;
        }

        /* GRID */
        .projects-grid {
          display: grid;
          grid-template-columns: repeat(2, 1fr);
          gap: 22px;
        }

        .project-card {
          background: rgba(255,255,255,0.04);
          border: 1px solid rgba(56,189,248,0.2);
          padding: 22px;
          border-radius: 16px;
          position: relative;
          transition: 0.3s;
        }

        .project-card:hover {
          transform: translateY(-6px);
          border-color: #38BDF8;
          box-shadow: 0 0 25px rgba(56,189,248,0.25);
        }

        /* BADGE */
        .badge {
          position: absolute;
          top: 12px;
          right: 12px;
          width: 30px;
          height: 30px;
          border-radius: 8px;

          display: flex;
          align-items: center;
          justify-content: center;

          font-size: 12px;
          font-weight: 600;

          color: #0b1220;
          background: linear-gradient(135deg, #38BDF8, #60a5fa);
          box-shadow: 0 0 10px rgba(56,189,248,0.3);
        }

        .project-icon {
          font-size: 28px;
          color: #38BDF8;
          margin-bottom: 10px;
        }

        /* STATIC COGNI FLOW ICON */
        .project-icon.cogni {
          color: #38BDF8;
          filter: drop-shadow(0 0 8px rgba(56,189,248,0.4));
          animation: none;
        }

        h3 {
          color: #e2e8f0;
          margin-bottom: 8px;
        }

        p {
          color: #cbd5e1;
          font-size: 14px;
          line-height: 1.6;
        }

        /* TECH TAGS */
        .tech-tags {
          margin-top: 12px;
          display: flex;
          flex-wrap: wrap;
          gap: 8px;
        }

        .tech-tags span {
          font-size: 12px;
          padding: 4px 10px;
          border-radius: 20px;
          background: rgba(56,189,248,0.1);
          border: 1px solid rgba(56,189,248,0.3);
          color: #38BDF8;
