        /* ACHIEVEMENTS */
        .achievements-grid {
          display: grid;
          grid-template-columns: repeat(2, 1fr);
          gap: 18px;
        }

        .achievement-card {
          display: flex;
          gap: 12px;
          align-items: flex-start;
          background: rgba(255,255,255,0.04);
          padding: 18px;
          border-radius: 14px;
          border: 1px solid rgba(56,189,248,0.15);
          transition: 0.3s;
