        .achievement-card:hover {
          transform: translateY(-4px);
          border-color: #38BDF8;
        }

        .achievement-icon {
          font-size: 24px;
          color: #38BDF8;
        }

        @media (max-width: 900px) {
          .projects-grid,
          .achievements-grid {
            grid-template-columns: 1fr;
          }
        }

      `}</style>

    </section>
